def add(cid,rid,name,work,period,pop,excluded,desc,values,bounds,bases,facts,assumptions,qualification,regime=3,zero=True,proxy=False,synthetic=False,extra=None,continuity=None,projection=None):
 refs=D['decisions'][cid]['source_ids']+(extra or [])
 r=guessed_record(cid,rid,name,work,name,['comic'],continuity or 'Named comic setting and stated period only',period,pop,excluded,desc,values,bounds,bases,refs,regime,facts,assumptions,qualification,zero=zero,proxy=proxy)
