(.95,-.95,.1),([.55,1],[-1,-.55],[0,.65]),('Repair-material dependence and predation weaken secure bodily support.','Synthetic independence coexists with coercive tribal leadership.','Active tribal persons retain resource, repair and caring roles; wreckage is excluded.'),
